namespace ghidra.app.plugin.core.symboltree.actions;

using docking.action;
using ghidra.app.context;
using ghidra.app.context;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.program.model.symbol;
using ghidra.util;

public class PinSymbolAction : ProgramSymbolContextAction {

	public PinSymbolAction(string owner, string popupGroup) : base("Pin Symbol", owner)
    {
		setPopupMenuData(new MenuData(new string[] { "Set Pinned" }, popupGroup));
		setDescription(
			"Pins the symbol(s) to the address so that it is unaffected by memory block moves or image base changes.");
		setHelpLocation(new HelpLocation("SymbolTablePlugin", "Pinning a Symbol"));
	}

	private bool canPinSymbol(Symbol symbol) {
		SymbolType type = symbol.getSymbolType();
		return (type == SymbolType.LABEL || type == SymbolType.FUNCTION) && !symbol.isExternal() &&
			!symbol.isPinned();
	}

	/* @Override */
	protected void actionPerformed(ProgramSymbolActionContext context) {
		Program program = context.getProgram();
		int transactionID = program.startTransaction("Pin Symbol(s)");
		try {
			foreach (Symbol symbol in context.getSymbols()) {
				if (canPinSymbol(symbol)) {
					symbol.setPinned(true);
				}
			}
		}
		finally {
			program.endTransaction(transactionID, true);
		}
	}

	/* @Override */
	protected bool isEnabledForContext(ProgramSymbolActionContext context) {
		foreach (Symbol symbol in context.getSymbols()) {
			if (canPinSymbol(symbol)) {
				return true;
			}
		}
		return false;
	}

}
